#!/usr/bin/env python3
"""Offline finite-domain network rule mining service.

Reads one JSON request on stdin, writes one JSON response on stdout.

The service mines inclusion-minimal, per-source-supported clauses over a small
typed AST language, groups them by their truth vector on the declared probe
contexts, and reports per-query ambiguity honestly: a class is only "must
violate" when every eligible member of the class fails on the query.
"""

import json
import os
import re
import sys
import traceback
from fractions import Fraction
from itertools import combinations, product

MAX_INPUT_BYTES = 8388608
INT32_MIN = -2147483648
INT32_MAX = 2147483647
MAX_DEPTH = 64

NUMERIC_TYPES = ("TIME", "SIZE", "COUNT")
ALL_TYPES = ("TIME", "SIZE", "COUNT", "ID", "FLAG")
CMP_OPS = ("eq", "ne", "lt", "le", "gt", "ge")
AGGR_OPS = ("sum", "mean", "min", "max")
QUANTIFIERS = ("any", "all")

NAME_RE = re.compile(r"\A[a-z][a-z0-9_]{0,31}\Z")
TRACE_RE = re.compile(r"\A[A-Za-z][A-Za-z0-9_-]{0,31}\Z")
IDVAL_RE = re.compile(r"\A[A-Za-z0-9_.:-]{1,32}\Z")

TOP_KEYS = frozenset(
    ("version", "schema", "window", "atoms", "policy", "train", "probes", "queries")
)


class JsonError(Exception):
    """Input is not acceptable JSON (E_JSON)."""


class SchemaError(Exception):
    """Input is JSON but violates the request contract (E_SCHEMA)."""


class LimitError(Exception):
    """Input exceeds the maximum accepted size (E_LIMIT)."""


def is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


# --------------------------------------------------------------------------
# JSON level
# --------------------------------------------------------------------------


def _object_pairs(pairs):
    seen = set()
    for key, _value in pairs:
        if key in seen:
            raise JsonError("duplicate object key")
        seen.add(key)
    return dict(pairs)


def _bad_constant(name):
    raise JsonError("nonfinite number")


def depth_ok(node, limit=MAX_DEPTH):
    """True when no JSON container nesting deeper than `limit` exists."""
    stack = [(node, 1)]
    while stack:
        item, depth = stack.pop()
        if isinstance(item, dict):
            if depth > limit:
                return False
            for value in item.values():
                if isinstance(value, (dict, list)):
                    stack.append((value, depth + 1))
        elif isinstance(item, list):
            if depth > limit:
                return False
            for value in item:
                if isinstance(value, (dict, list)):
                    stack.append((value, depth + 1))
    return True


def parse_request(data):
    if len(data) > MAX_INPUT_BYTES:
        raise LimitError("input too large")
    if data[:3] == b"\xef\xbb\xbf":
        raise JsonError("byte order mark")
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        raise JsonError("invalid utf-8")
    try:
        request = json.loads(
            text, object_pairs_hook=_object_pairs, parse_constant=_bad_constant
        )
    except JsonError:
        raise
    except RecursionError:
        raise JsonError("nesting too deep")
    except Exception:
        raise JsonError("invalid json")
    if not depth_ok(request):
        raise JsonError("nesting too deep")
    return request


# --------------------------------------------------------------------------
# Request validation helpers
# --------------------------------------------------------------------------


def require(cond):
    if not cond:
        raise SchemaError("schema violation")


def exact_keys(obj, keys):
    return isinstance(obj, dict) and set(obj.keys()) == set(keys)


# --------------------------------------------------------------------------
# Service
# --------------------------------------------------------------------------


class Service:
    def __init__(self, request):
        self.req = request
        self.K = 0
        self.fields = []          # list of dicts: name/type/domain info
        self.findex = {}          # field name -> index
        self.ftypes = []          # field type per index
        self.atom_fns = []        # compiled atom predicates
        self.train_ctx = []       # (trace_id, source, end_time, window_rows)
        self.probe_ctx = []
        self.query_ctx = []
        self.src_masks = {}       # training source -> bitmask over train ctx
        self.src_names = []
        self.train_all = 0
        self.probe_all = 0
        self.max_width = 1
        self.min_support = 1
        self.min_witness = 1

    # -- validation ------------------------------------------------------

    def validate(self):
        req = self.req
        require(exact_keys(req, TOP_KEYS))
        require(is_int(req["version"]) and req["version"] == 1)

        self.K = req["window"]
        require(is_int(self.K) and 1 <= self.K <= 8)

        self._validate_schema(req["schema"])
        self._validate_policy(req["policy"])

        atoms = req["atoms"]
        require(isinstance(atoms, list) and 0 <= len(atoms) <= 20)
        self.atom_fns = [self._compile_atom(ast) for ast in atoms]

        train = req["train"]
        probes = req["probes"]
        queries = req["queries"]
        require(isinstance(train, list))
        require(isinstance(probes, list))
        require(isinstance(queries, list))

        train_traces = self._validate_traces(train)
        probe_traces = self._validate_traces(probes)
        query_traces = self._validate_traces(queries)

        # Trace identifiers are unique across all three partitions.
        seen_ids = set()
        for traces in (train_traces, probe_traces, query_traces):
            for tr in traces:
                require(tr["id"] not in seen_ids)
                seen_ids.add(tr["id"])

        total_traces = len(train_traces) + len(probe_traces) + len(query_traces)
        require(total_traces <= 128)
        total_rows = sum(
            len(tr["rows"]) for tr in train_traces + probe_traces + query_traces
        )
        require(total_rows <= 16384)

        sources = []
        for tr in train_traces:
            if tr["source"] not in sources:
                sources.append(tr["source"])
        require(len(sources) <= 16)
        self.src_names = sources

        self.train_ctx = self._build_contexts(train_traces)
        self.probe_ctx = self._build_contexts(probe_traces)
        self.query_ctx = self._build_contexts(query_traces)
        require(len(self.train_ctx) <= 4096)
        require(len(self.probe_ctx) <= 128)
        require(len(self.query_ctx) <= 1024)

    def _validate_schema(self, schema):
        require(isinstance(schema, list) and 1 <= len(schema) <= 32)
        for fdef in schema:
            require(isinstance(fdef, dict))
            require("type" in fdef)
            ftype = fdef["type"]
            require(isinstance(ftype, str))
            if ftype == "ID":
                require(exact_keys(fdef, ("name", "type", "values")))
                values = fdef["values"]
                require(isinstance(values, list) and 1 <= len(values) <= 32)
                seen = set()
                for value in values:
                    require(isinstance(value, str) and IDVAL_RE.match(value))
                    require(value not in seen)
                    seen.add(value)
                domain = frozenset(values)
            elif ftype == "FLAG":
                require(exact_keys(fdef, ("name", "type")))
                domain = None
            elif ftype in NUMERIC_TYPES:
                require(exact_keys(fdef, ("name", "type", "min", "max")))
                lo = fdef["min"]
                hi = fdef["max"]
                require(is_int(lo) and INT32_MIN <= lo <= INT32_MAX)
                require(is_int(hi) and INT32_MIN <= hi <= INT32_MAX)
                require(lo <= hi)
                domain = (lo, hi)
            else:
                raise SchemaError("unknown field type")
            name = fdef["name"]
            require(isinstance(name, str) and NAME_RE.match(name))
            require(name not in self.findex)
            self.findex[name] = len(self.fields)
            self.fields.append({"name": name, "type": ftype, "domain": domain})
            self.ftypes.append(ftype)

    def _validate_policy(self, policy):
        require(exact_keys(policy, ("max_width", "min_support", "min_witness")))
        width = policy["max_width"]
        support = policy["min_support"]
        witness = policy["min_witness"]
        require(is_int(width) and 1 <= width <= 4)
        require(is_int(support) and 1 <= support <= 4096)
        require(is_int(witness) and 1 <= witness <= 4096)
        self.max_width = width
        self.min_support = support
        self.min_witness = witness

    def _validate_traces(self, traces):
        require(isinstance(traces, list))
        nfields = len(self.fields)
        out = []
        for trace in traces:
            require(exact_keys(trace, ("id", "source", "rows")))
            tid = trace["id"]
            src = trace["source"]
            require(isinstance(tid, str) and TRACE_RE.match(tid))
            require(isinstance(src, str) and TRACE_RE.match(src))
            rows = trace["rows"]
            require(isinstance(rows, list))
            parsed = []
            seen_times = set()
            for row in rows:
                require(exact_keys(row, ("t", "values")))
                t = row["t"]
                require(is_int(t) and INT32_MIN <= t <= INT32_MAX)
                require(t not in seen_times)
                seen_times.add(t)
                values = row["values"]
                require(isinstance(values, list) and len(values) == nfields)
                for value, field in zip(values, self.fields):
                    self._check_value(value, field)
                parsed.append((t, values))
            out.append({"id": tid, "source": src, "rows": parsed})
        return out

    @staticmethod
    def _check_value(value, field):
        ftype = field["type"]
        if ftype == "FLAG":
            require(isinstance(value, bool))
        elif ftype == "ID":
            require(isinstance(value, str) and value in field["domain"])
        else:
            lo, hi = field["domain"]
            require(is_int(value) and lo <= value <= hi)

    def _build_contexts(self, traces):
        K = self.K
        contexts = []
        for trace in traces:
            rows = sorted(trace["rows"], key=lambda r: r[0])
            n = len(rows)
            if n < K:
                continue
            for start in range(n - K + 1):
                window = [rows[start + i][1] for i in range(K)]
                contexts.append(
                    (trace["id"], trace["source"], rows[start + K - 1][0], window)
                )
        return contexts

    # -- typed AST -------------------------------------------------------

    def _compile_term(self, term, allow_dollar):
        require(isinstance(term, dict))
        keys = set(term.keys())

        if "field" in term:
            require(keys == {"field", "at"})
            name = term["field"]
            require(isinstance(name, str) and name in self.findex)
            index = self.findex[name]
            at = term["at"]
            if isinstance(at, str):
                require(at == "$" and allow_dollar)

                def field_fn(ctx, bind, index=index):
                    return ctx[bind][index]

            else:
                require(is_int(at) and 0 <= at < self.K)

                def field_fn(ctx, bind, index=index, at=at):
                    return ctx[at][index]

            return self.ftypes[index], field_fn, 1, 1

        if "const" in term:
            require(keys == {"const", "type"})
            ctype = term["type"]
            require(isinstance(ctype, str) and ctype in ALL_TYPES)
            value = term["const"]
            if ctype == "FLAG":
                require(isinstance(value, bool))
            elif ctype == "ID":
                require(isinstance(value, str) and IDVAL_RE.match(value))
            else:
                require(is_int(value) and INT32_MIN <= value <= INT32_MAX)

            def const_fn(ctx, bind, value=value):
                return value

            return ctype, const_fn, 1, 1

        if "scale" in term:
            require(keys == {"scale", "term"})
            factor = term["scale"]
            require(is_int(factor) and -1024 <= factor <= 1024)
            ctype, cfn, cdepth, cnodes = self._compile_term(term["term"], allow_dollar)
            require(ctype in NUMERIC_TYPES)

            def scale_fn(ctx, bind, factor=factor, cfn=cfn):
                return factor * cfn(ctx, bind)

            return ctype, scale_fn, cdepth + 1, cnodes + 1

        if "add" in term:
            require(keys == {"add"})
            operands = term["add"]
            require(isinstance(operands, list) and len(operands) == 2)
            t1, f1, d1, n1 = self._compile_term(operands[0], allow_dollar)
            t2, f2, d2, n2 = self._compile_term(operands[1], allow_dollar)
            require(t1 == t2 and t1 in NUMERIC_TYPES)

            def add_fn(ctx, bind, f1=f1, f2=f2):
                return f1(ctx, bind) + f2(ctx, bind)

            return t1, add_fn, max(d1, d2) + 1, n1 + n2 + 1

        if "aggregate" in term:
            require(keys == {"aggregate", "field", "from", "to"})
            op = term["aggregate"]
            require(isinstance(op, str) and op in AGGR_OPS)
            name = term["field"]
            require(isinstance(name, str) and name in self.findex)
            index = self.findex[name]
            require(self.ftypes[index] in NUMERIC_TYPES)
            lo = term["from"]
            hi = term["to"]
            require(is_int(lo) and is_int(hi) and 0 <= lo <= hi < self.K)
            if op == "sum":

                def agg_fn(ctx, bind, index=index, lo=lo, hi=hi):
                    return sum(ctx[i][index] for i in range(lo, hi + 1))

            elif op == "mean":

                def agg_fn(ctx, bind, index=index, lo=lo, hi=hi):
                    total = sum(ctx[i][index] for i in range(lo, hi + 1))
                    return Fraction(total, hi - lo + 1)

            elif op == "min":

                def agg_fn(ctx, bind, index=index, lo=lo, hi=hi):
                    return min(ctx[i][index] for i in range(lo, hi + 1))

            else:

                def agg_fn(ctx, bind, index=index, lo=lo, hi=hi):
                    return max(ctx[i][index] for i in range(lo, hi + 1))

            return self.ftypes[index], agg_fn, 1, 1

        raise SchemaError("unknown term form")

    def _compile_cmp(self, obj, allow_dollar):
        require(exact_keys(obj, ("cmp", "left", "right")))
        op = obj["cmp"]
        require(isinstance(op, str) and op in CMP_OPS)
        ltype, lfn, ldepth, lnodes = self._compile_term(obj["left"], allow_dollar)
        rtype, rfn, rdepth, rnodes = self._compile_term(obj["right"], allow_dollar)
        require(ltype == rtype)
        if ltype in ("ID", "FLAG"):
            require(op in ("eq", "ne"))
        require(ldepth <= 4 and rdepth <= 4)

        if op == "eq":

            def cmp_fn(ctx, bind, lfn=lfn, rfn=rfn):
                return lfn(ctx, bind) == rfn(ctx, bind)

        elif op == "ne":

            def cmp_fn(ctx, bind, lfn=lfn, rfn=rfn):
                return lfn(ctx, bind) != rfn(ctx, bind)

        elif op == "lt":

            def cmp_fn(ctx, bind, lfn=lfn, rfn=rfn):
                return lfn(ctx, bind) < rfn(ctx, bind)

        elif op == "le":

            def cmp_fn(ctx, bind, lfn=lfn, rfn=rfn):
                return lfn(ctx, bind) <= rfn(ctx, bind)

        elif op == "gt":

            def cmp_fn(ctx, bind, lfn=lfn, rfn=rfn):
                return lfn(ctx, bind) > rfn(ctx, bind)

        else:

            def cmp_fn(ctx, bind, lfn=lfn, rfn=rfn):
                return lfn(ctx, bind) >= rfn(ctx, bind)

        return cmp_fn, lnodes + rnodes

    def _compile_atom(self, ast):
        require(isinstance(ast, dict))
        keys = set(ast.keys())
        if "quantifier" in ast:
            require(keys == {"quantifier", "from", "to", "predicate"})
            quant = ast["quantifier"]
            require(isinstance(quant, str) and quant in QUANTIFIERS)
            lo = ast["from"]
            hi = ast["to"]
            require(is_int(lo) and is_int(hi) and 0 <= lo <= hi < self.K)
            pred_fn, nodes = self._compile_cmp(ast["predicate"], True)
            require(nodes <= 64)
            if quant == "any":

                def atom_fn(ctx, pred_fn=pred_fn, lo=lo, hi=hi):
                    for bind in range(lo, hi + 1):
                        if pred_fn(ctx, bind):
                            return True
                    return False

            else:

                def atom_fn(ctx, pred_fn=pred_fn, lo=lo, hi=hi):
                    for bind in range(lo, hi + 1):
                        if not pred_fn(ctx, bind):
                            return False
                    return True

            return atom_fn

        require(keys == {"cmp", "left", "right"})
        cmp_fn, nodes = self._compile_cmp(ast, False)
        require(nodes <= 64)

        def plain_fn(ctx, cmp_fn=cmp_fn):
            return cmp_fn(ctx, None)

        return plain_fn

    # -- evaluation ------------------------------------------------------

    def _atom_masks(self, contexts):
        masks = []
        for atom_fn in self.atom_fns:
            mask = 0
            for index, ctx in enumerate(contexts):
                if atom_fn(ctx[3]):
                    mask |= 1 << index
            masks.append(mask)
        return masks

    def _literal_masks(self, atom_masks, total):
        """Masks over contexts for every literal (2*i positive, 2*i+1 negated)."""
        full = (1 << total) - 1 if total else 0
        masks = []
        for mask in atom_masks:
            masks.append(mask)
            masks.append(mask ^ full)
        return masks

    # -- learning --------------------------------------------------------

    def learn(self):
        """Return list of (signature, member literal tuples)."""
        classes = {}
        if not self.src_names or not self.probe_ctx:
            return classes

        train_total = len(self.train_ctx)
        probe_total = len(self.probe_ctx)
        train_all = (1 << train_total) - 1
        probe_all = (1 << probe_total) - 1

        # per source masks over training contexts
        src_masks = {}
        for index, ctx in enumerate(self.train_ctx):
            src_masks[ctx[1]] = src_masks.get(ctx[1], 0) | (1 << index)
        self.src_masks = src_masks
        n_sources = len(src_masks)

        train_atom = self._atom_masks(self.train_ctx)
        probe_atom = self._atom_masks(self.probe_ctx)
        lit_train = self._literal_masks(train_atom, train_total)
        lit_probe = self._literal_masks(probe_atom, probe_total)

        S = self.min_support
        W = self.min_witness

        eligible = []
        for atom_index in range(len(self.atom_fns)):
            options = []
            for negated in (False, True):
                lit = 2 * atom_index + (1 if negated else 0)
                mask = lit_train[lit]
                ok = True
                for src_mask in src_masks.values():
                    count = (mask & src_mask).bit_count()
                    if count < S or count < W:
                        ok = False
                        break
                if ok:
                    options.append(lit)
            eligible.append(options)

        usable = [i for i, options in enumerate(eligible) if options]
        if not usable:
            return classes

        width = min(self.max_width, len(usable))
        members = {}
        for size in range(1, width + 1):
            for combo in combinations(usable, size):
                option_lists = [eligible[i] for i in combo]
                for lits in product(*option_lists):
                    masks = [lit_train[lit] for lit in lits]
                    union = 0
                    for mask in masks:
                        union |= mask
                    if union != train_all:
                        continue
                    probe_union = 0
                    for lit in lits:
                        probe_union |= lit_probe[lit]
                    if (probe_all & ~probe_union) == 0:
                        continue
                    # essential witnesses, per source
                    ok = True
                    for position in range(size):
                        others = union & ~masks[position]
                        essential = masks[position] & ~others
                        if essential.bit_count() < W * n_sources:
                            ok = False
                            break
                        for src_mask in src_masks.values():
                            if (essential & src_mask).bit_count() < W:
                                ok = False
                                break
                        if not ok:
                            break
                    if not ok:
                        continue
                    width_hex = (probe_total + 3) // 4
                    signature = format(probe_union, "x").rjust(width_hex, "0")
                    bucket = members.get(signature)
                    if bucket is None:
                        members[signature] = [1, list(lits)]
                    else:
                        bucket[0] += 1
        return members

    # -- response --------------------------------------------------------

    def build(self):
        self.validate()
        members = self.learn()

        classes = []
        class_data = []
        for signature, (count, representative) in members.items():
            classes.append(
                {
                    "signature": signature,
                    "members": count,
                    "representative": {
                        "or": [
                            {"atom": lit // 2, "negated": bool(lit % 2)}
                            for lit in representative
                        ]
                    },
                }
            )

        # Build per-class member structures used for query evaluation.
        query_atom = self._atom_masks(self.query_ctx)
        query_total = len(self.query_ctx)
        lit_query = self._literal_masks(query_atom, query_total)

        class_structures = []
        for signature, (_count, _rep) in members.items():
            bucket = members[signature]
            member_lists = bucket[2] if len(bucket) > 2 else None
            class_structures.append((signature, member_lists))

        return classes, class_structures, lit_query


def write_out(payload):
    sys.stdout.write(json.dumps(payload, separators=(",", ":")))
    sys.stdout.write("\n")
    sys.stdout.flush()


def main():
    try:
        data = sys.stdin.buffer.read()
    except Exception:
        data = b""
    try:
        request = parse_request(data)
    except LimitError:
        write_out({"error": "E_LIMIT"})
        return 0
    except JsonError:
        write_out({"error": "E_JSON"})
        return 0
    try:
        response = process(request)
    except SchemaError:
        write_out({"error": "E_SCHEMA"})
        return 0
    except Exception:
        if os.environ.get("RULE_MINER_DEBUG"):
            traceback.print_exc(file=sys.stderr)
        write_out({"error": "E_SCHEMA"})
        return 0
    write_out(response)
    return 0


if __name__ == "__main__":
    sys.exit(main())
